macro_rules! check_type_defn {
    () => {
        # [doc = " In a type definition, we check that to ensure that the types of the fields are well-formed."] fn check_type_defn < 'tcx > (tcx : TyCtxt < 'tcx > , item : & hir :: Item < 'tcx > , all_sized : bool ,) -> Result < () , ErrorGuaranteed > { let _ = tcx . representability (item . owner_id . def_id) ; let adt_def = tcx . adt_def (item . owner_id) ; enter_wf_checking_ctxt (tcx , item . owner_id . def_id , | wfcx | { let variants = adt_def . variants () ; let packed = adt_def . repr () . packed () ; for variant in variants . iter () { for field in & variant . fields { if let Some (def_id) = field . value && let Some (_ty) = tcx . type_of (def_id) . no_bound_vars () { if let Some (def_id) = def_id . as_local () && let hir :: Node :: AnonConst (anon) = tcx . hir_node_by_def_id (def_id) && let expr = & tcx . hir_body (anon . body) . value && let hir :: ExprKind :: Path (hir :: QPath :: Resolved (None , path)) = expr . kind && let Res :: Def (DefKind :: ConstParam , _def_id) = path . res { } else { let _ = tcx . const_eval_poly (def_id) ; } } let field_id = field . did . expect_local () ; let hir :: FieldDef { ty : hir_ty , .. } = tcx . hir_node_by_def_id (field_id) . expect_field () ; let ty = wfcx . deeply_normalize (hir_ty . span , None , tcx . type_of (field . did) . instantiate_identity () ,) ; wfcx . register_wf_obligation (hir_ty . span , Some (WellFormedLoc :: Ty (field_id)) , ty . into () ,) } let needs_drop_copy = | | { packed && { let ty = tcx . type_of (variant . tail () . did) . instantiate_identity () ; let ty = tcx . erase_and_anonymize_regions (ty) ; assert ! (! ty . has_infer ()) ; ty . needs_drop (tcx , wfcx . infcx . typing_env (wfcx . param_env)) } } ; let all_sized = all_sized || variant . fields . is_empty () || needs_drop_copy () ; let unsized_len = if all_sized { 0 } else { 1 } ; for (idx , field) in variant . fields . raw [.. variant . fields . len () - unsized_len] . iter () . enumerate () { let last = idx == variant . fields . len () - 1 ; let field_id = field . did . expect_local () ; let hir :: FieldDef { ty : hir_ty , .. } = tcx . hir_node_by_def_id (field_id) . expect_field () ; let ty = wfcx . normalize (hir_ty . span , None , tcx . type_of (field . did) . instantiate_identity () ,) ; wfcx . register_bound (traits :: ObligationCause :: new (hir_ty . span , wfcx . body_def_id , ObligationCauseCode :: FieldSized { adt_kind : match & item . kind { ItemKind :: Struct (..) => AdtKind :: Struct , ItemKind :: Union (..) => AdtKind :: Union , ItemKind :: Enum (..) => AdtKind :: Enum , kind => span_bug ! (item . span , "should be wfchecking an ADT, got {kind:?}") , } , span : hir_ty . span , last , } ,) , wfcx . param_env , ty , tcx . require_lang_item (LangItem :: Sized , hir_ty . span) ,) ; } if let ty :: VariantDiscr :: Explicit (discr_def_id) = variant . discr { match tcx . const_eval_poly (discr_def_id) { Ok (_) => { } Err (ErrorHandled :: Reported (..)) => { } Err (ErrorHandled :: TooGeneric (sp)) => { span_bug ! (sp , "enum variant discr was too generic to eval") } } } } check_where_clauses (wfcx , item . owner_id . def_id) ; Ok (()) }) }
    };
}

check_type_defn!()